const nw = msg.data.new_state;
const ow = msg.data.old_state;

if (!nw || !nw.attributes || !nw.attributes.lista_przedmiotow) return null;

const noweOceny = nw.attributes.lista_przedmiotow;
// Pamięć podręczna ocen (context)
let stareOceny = context.get('oceny_cache') || (ow ? ow.attributes.lista_przedmiotow : []);
context.set('oceny_cache', noweOceny);

const imie = nw.attributes.friendly_name ? nw.attributes.friendly_name.split(': ')[1] : "Uczeń";
let wiadomosci = [];

noweOceny.forEach(nowyObj => {
    const staryObj = stareOceny.find(s => s.przedmiot === nowyObj.przedmiot);
    const staraOcenyCiag = staryObj ? staryObj.oceny_ciag : "";

    if (nowyObj.oceny_ciag.length > staraOcenyCiag.length) {
        let nowaCzesc = nowyObj.oceny_ciag.replace(staraOcenyCiag, "").trim();
        let kandydaci = nowaCzesc.split(/\s{2,}/);

        kandydaci.forEach(k => {
            if (!k) return;
            let ocenaCzysta = k.replace(/\s*\(\d{2}\.\d{2}\)/g, "").trim();
            if (ocenaCzysta) {
                // TUTAJ: Tworzymy payload idealnie pod Home Assistant
                wiadomosci.push({
                    payload: {
                        title: `Nowa ocena: ${nowyObj.przedmiot}`,
                        message: `${imie} otrzymał(a) **${ocenaCzysta}** z przedmiotu **${nowyObj.przedmiot}**`,
                        notification_id: "vultron_ocena_" + nowyObj.przedmiot.replace(/\s/g, '_')
                    }
                });
            }
        });
    }
});

if (wiadomosci.length > 0) return [wiadomosci];
return null;

// Pobieramy wiadomość tekstową
let tekst = msg.payload.message;

if (tekst && tekst.includes("**")) {
    // Wyciągamy to, co jest między gwiazdkami
    let ocenaRaw = tekst.split("**")[1].trim();

    // CAŁKOWICIE nadpisujemy payload, aby nie było tam nic poza oceną
    // Teraz msg.payload będzie zawierał np. "4" albo "5+"
    msg.payload = ocenaRaw; 

    // Opcjonalnie: jeśli chcesz, żeby Node-RED widział to jako liczbę do porównań (np. w Switch)
    // odkomentuj poniższą linię (usuń //), ale wtedy stracisz plusy i minusy (zmienią się w ułamki)
    // msg.payload = parseFloat(ocenaRaw.replace('+', '.5').replace('-', '.75'));

    return msg;
}

// Jeśli nie znaleziono oceny, zatrzymaj przepływ
return null;
